        private char peek() {
            if (at >= text.length()) {
                throw new IllegalArgumentException("unexpected end of input");
            }
            return text.charAt(at);
        }

        private void expect(String literal) {
            if (!text.startsWith(literal, at)) {
                throw new IllegalArgumentException("expected " + literal + " at " + at);
            }
            at += literal.length();
        }

        private Object value() {
            char ch = peek();
            if (ch == '{') {
                return object();
            }
            if (ch == '[') {
                return array();
            }
            if (ch == '"') {
                return string();
            }
            if (ch == 't') {
                expect("true");
                return Boolean.TRUE;
            }
            if (ch == 'f') {
                expect("false");
                return Boolean.FALSE;
            }
            if (ch == 'n') {
                expect("null");
                return null;
            }
            return number();
        }

        private Map<String, Object> object() {
            Map<String, Object> out = new LinkedHashMap<String, Object>();
            at++;
            skip();
            if (peek() == '}') {
                at++;
                return out;
            }
            while (true) {
                skip();
                String key = string();
                skip();
                if (peek() != ':') {
                    throw new IllegalArgumentException("expected : at " + at);
                }
                at++;
                skip();
                out.put(key, value());
                skip();
                char ch = peek();
                if (ch == ',') {
                    at++;
                    continue;
                }
                if (ch == '}') {
                    at++;
                    return out;
                }
                throw new IllegalArgumentException("expected , or } at " + at);
            }
        }

        private List<Object> array() {
            List<Object> out = new ArrayList<Object>();
            at++;
            skip();
            if (peek() == ']') {
                at++;
                return out;
            }
            while (true) {
                skip();
                out.add(value());
                skip();
                char ch = peek();
                if (ch == ',') {
                    at++;
                    continue;
                }
                if (ch == ']') {
                    at++;
                    return out;
                }
                throw new IllegalArgumentException("expected , or ] at " + at);
            }
        }

        private String string() {
            if (peek() != '"') {
                throw new IllegalArgumentException("expected a string at " + at);
            }
            at++;
            StringBuilder out = new StringBuilder();
            while (true) {
                if (at >= text.length()) {
                    throw new IllegalArgumentException("unterminated string");
                }
                char ch = text.charAt(at++);
                if (ch == '"') {
                    return out.toString();
                }
                if (ch != '\\') {
                    if (ch < 0x20) {
                        throw new IllegalArgumentException("control character in a string at " + at);
                    }
                    out.append(ch);
                    continue;
                }
                char escape = text.charAt(at++);
                if (escape == 'u') {
                    out.append((char) Integer.parseInt(text.substring(at, at + 4), 16));
                    at += 4;
                } else if (escape == 'n') {
                    out.append('\n');
                } else if (escape == 't') {
                    out.append('\t');
                } else if (escape == 'r') {
                    out.append('\r');
                } else if (escape == 'b') {
                    out.append('\b');
                } else if (escape == 'f') {
                    out.append('\f');
                } else if (escape == '"' || escape == '\\' || escape == '/') {
                    out.append(escape);
                } else {
                    throw new IllegalArgumentException("unknown escape at " + at);
                }
            }
        }

        private Object number() {
            int start = at;
            if (at < text.length() && text.charAt(at) == '-') {
                at++;
            }
            while (at < text.length() && Character.isDigit(text.charAt(at))) {
                at++;
            }
            boolean floating = false;
            if (at < text.length() && text.charAt(at) == '.') {
                floating = true;
                at++;
                while (at < text.length() && Character.isDigit(text.charAt(at))) {
                    at++;
                }
            }
            if (at < text.length() && (text.charAt(at) == 'e' || text.charAt(at) == 'E')) {
                floating = true;
                at++;
                if (at < text.length() && (text.charAt(at) == '+' || text.charAt(at) == '-')) {
                    at++;
                }
                while (at < text.length() && Character.isDigit(text.charAt(at))) {
                    at++;
                }
            }
            String token = text.substring(start, at);
            if (token.isEmpty() || "-".equals(token)) {
                throw new IllegalArgumentException("expected a value at " + start);
            }
            try {
                return floating ? (Object) Double.valueOf(token) : (Object) new BigInteger(token);
            } catch (NumberFormatException exc) {
                throw new IllegalArgumentException("not a number: " + token);
            }
        }
